css:
.dir-c{width:720px;height:460px;box-sizing:border-box;position:relative;overflow:hidden;padding:20px 25px 16px;background:#e4edf7;color:#173650;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Noto Sans SC",sans-serif;font-size:16px;line-height:1.55;font-weight:400;isolation:isolate}
.dir-c *{box-sizing:border-box}
.dir-c .c-masthead{display:flex;align-items:center;justify-content:space-between;height:37px;border-bottom:2px solid #173650;padding-bottom:10px}
.dir-c .c-identity{display:flex;align-items:center;gap:10px}
.dir-c .c-drawer-mark{font-size:23px;line-height:1;color:#173650}
.dir-c h1{font-family:"Songti SC","STSong","SimSun",serif;font-size:25px;font-weight:600;line-height:1.2;margin:0;letter-spacing:.07em}
.dir-c .c-year-range{font-family:Consolas,"SFMono-Regular",monospace;font-size:14px;margin-left:6px}
.dir-c .c-sample-label{font-size:12px;color:#49667f;border:1px solid #9aafc3;padding:1px 6px}
.dir-c .c-archive-caption{display:flex;justify-content:space-between;align-items:center;height:29px;color:#49667f;font-size:12px}
.dir-c .c-archive-caption>span:first-child{font-family:Consolas,"SFMono-Regular",monospace;letter-spacing:.1em;text-transform:uppercase}
.dir-c .c-drawer{position:relative;height:340px;margin-top:8px}
.dir-c .c-folder-tabs{height:32px;position:relative;z-index:4;display:flex;gap:3px;align-items:flex-start;padding-left:0}
.dir-c .c-tab{display:flex;align-items:center;justify-content:space-between;gap:21px;height:34px;border:1px solid #7e99b3;border-bottom:0;border-radius:6px 7px 0 0;padding:6px 14px;background:#c8d7e7;color:#23435f;text-decoration:none;font-size:14px;white-space:nowrap}
.dir-c .c-tab span{font:13px Consolas,"SFMono-Regular",monospace;color:#486780}
.dir-c .c-tab-current{width:188px;background:#fff;border-color:#7e99b3;height:37px;padding-top:7px;font-weight:600}
.dir-c .c-tab-route{width:166px;margin-top:6px;background:#b8cce0}
.dir-c .c-tab-question{width:166px;margin-top:12px;background:#ccdbea}
.dir-c .c-paper-stack{height:308px;position:relative;border:1px solid #829bb4;background:#c0d0e1;box-shadow:0 6px 0 #b3c6da,0 8px 0 #8ea8c1}
.dir-c .c-cover-sheet{position:absolute;left:0;top:0;width:398px;height:306px;z-index:1;background:#fff;padding:17px 23px 16px;border:1px solid #cad6e2;border-top:0;box-shadow:4px 0 8px #1736500c}
.dir-c .c-volume-label{display:flex;justify-content:space-between;gap:8px;margin-right:20px;font-size:12px;color:#55728a;border-bottom:1px solid #cad6e2;padding-bottom:9px}
.dir-c .c-volume-label>span:last-child{font-family:Consolas,"SFMono-Regular",monospace}
.dir-c .c-slogan{font-family:"Songti SC","STSong","SimSun",serif;font-size:30px;font-weight:600;line-height:1.43;letter-spacing:.06em;margin:18px 0 19px}
.dir-c .c-slogan span{display:block;white-space:nowrap}
.dir-c .c-stat-strip{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-right:12px;border-top:1px solid #b9cadb;padding-top:10px}
.dir-c .c-stat-strip>span{display:flex;flex-direction:column;font-size:12px;color:#49667f;white-space:nowrap}
.dir-c .c-stat-strip strong{font-family:Consolas,"SFMono-Regular",monospace;font-weight:400;color:#173650;font-size:26px;line-height:1.2;font-variant-numeric:tabular-nums}
.dir-c .c-project-footnote{font-size:12px;color:#55728a;margin-top:11px}
.dir-c .c-reading-sheet{position:absolute;right:11px;top:21px;width:288px;height:270px;z-index:2;background:#fbfdff;border:1px solid #829bb4;padding:13px 18px;box-shadow:-5px 4px 0 #1736500c;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#8da7c0 #edf3f9}
.dir-c .c-case-heading{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#49667f}
.dir-c .c-review-stamp{border:1px solid #a43a35;color:#a43a35;padding:0 6px;font-size:12px;letter-spacing:.07em}
.dir-c h3{font-family:"Songti SC","STSong","SimSun",serif;font-size:24px;line-height:1.3;margin:8px 0 4px;font-weight:600;letter-spacing:.04em}
.dir-c .c-case-meta{font-size:12px;color:#55728a;margin-bottom:10px}
.dir-c .c-doc-detail{border-top:1px solid #b9cadb}
.dir-c .c-doc-detail summary{cursor:pointer;display:flex;justify-content:space-between;align-items:center;list-style:none;padding:7px 0 5px;font-size:15px;color:#173650;font-weight:500}
.dir-c .c-doc-detail summary::-webkit-details-marker{display:none}
.dir-c .c-open-symbol{font-size:20px;font-weight:400;line-height:1;transition:transform 140ms cubic-bezier(.2,.7,.2,1)}
.dir-c .c-doc-detail[open] .c-open-symbol{transform:rotate(45deg)}
.dir-c .c-document-name{font-family:Consolas,"SFMono-Regular",monospace;font-size:11px;color:#49667f;line-height:1.5;overflow-wrap:anywhere;margin:0 0 6px}
.dir-c .c-doc-detail p{font-size:15px;line-height:1.65;margin:0;color:#23435f}
.dir-c .c-next-question{font-size:12px;line-height:1.6;color:#a43a35;border-top:1px dotted #c4d1de;margin-top:10px;padding-top:8px}
.dir-c .c-archive-route{position:absolute;left:25px;right:25px;bottom:9px;display:flex;justify-content:space-between;align-items:center;gap:7px;font-size:11px;color:#55728a;white-space:nowrap}
.dir-c .c-archive-route>span{display:flex;gap:7px;align-items:center}
.dir-c .c-archive-route b{font-size:12px;font-weight:400;color:#23435f}
.dir-c .c-path-arrow{color:#7e99b3}
.dir-c a:focus-visible,.dir-c summary:focus-visible{outline:2px solid #a43a35;outline-offset:2px}
.dir-c .c-tab:hover{background:#f3f7fc}
@media(prefers-reduced-motion:reduce){.dir-c .c-open-symbol{transition:none}}
